var maxDistance = function(colors) {
    if (colors[0] !== colors[colors.length - 1]) {
        return colors.length - 1;
    }

    let max = -Infinity;

    for (let i = 1; i < colors.length; i++) {
        if (colors[i] !== colors[0]) {
            max = Math.max(max, i, colors.length - 1 - i);
