/**
 * @param {number[]} colors
 * @return {number}
 */
var maxDistance = function(colors) {
    const n = colors.length;

    if (colors[0] !== colors[n - 1]) {
        return n - 1;
    }

    const target = colors[0];
    const len = Math.ceil(n / 2);

    for (let i = 1; i <= len; i++) {
        if (colors[i] !== target || colors[n - 1 - i] !== target) {
            return n - 1 - i;
        }
    }

    return -1;
};
